import{_ as n,C as o,c,o as i,aa as r,G as a}from"./chunks/framework.Cn7WEiMX.js";const _=JSON.parse('{"title":"以 Wavefront OBJ 格式导出世界数据","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/Dynmap/advanced-configuration/exporting-world-data-in-wavefront-obj-format.md","filePath":"wiki/Dynmap/advanced-configuration/exporting-world-data-in-wavefront-obj-format.md"}'),l={name:"wiki/Dynmap/advanced-configuration/exporting-world-data-in-wavefront-obj-format.md"};function p(m,e,s,f,x,y){const d=o("NolebaseGitContributors"),t=o("NolebaseGitChangelog");return i(),c("div",null,[e[0]||(e[0]=r('<h1 id="以-wavefront-obj-格式导出世界数据" tabindex="-1">以 Wavefront OBJ 格式导出世界数据 <a class="header-anchor" href="#以-wavefront-obj-格式导出世界数据" aria-label="Permalink to &quot;以 Wavefront OBJ 格式导出世界数据&quot;">​</a></h1> <p>在 1.9.3 版本之后，Dynmap 新增了生成与导出外部可读的 Wavefront OBJ 格式文件。这个功能受到一个独立工具 <a href="http://jmc2obj.net/" target="_blank" rel="noreferrer">jmc-2-obj</a> 的启发，允许服务器（或控制台）上的操作者选择导出世界数据为模型数据，可导入各种支持 Wavefront OBJ 工具——包括 Blender（免费开源的渲染与动画套件），Maxon Cinema 4D、Autodesk Maya，3D Studio Max 等。这些导出的模型可通过这些包以 Dynmap 不支持的方式渲染（包括高级光照、表面反射等）。鉴于 Dynmap 导出的 OBJ 格式与 jmc-2-obj 类似，这个程序的教程与文档提及的工具也适用于 Dynmap OBJ 文件。</p> <p>导出功能可通过 <code>/dynmapexp</code> 命令开始。这个命令可以控制导出的设置参数：</p> <ul><li><code>x0, y0, z0</code>：导出长方体区域的最小 XYZ 轴坐标</li> <li><code>x1, y1, z1</code>：导出长方体区域的最大 XYZ 轴坐标</li> <li><code>world</code>：导出指定的世界名称</li> <li><code>byChunk</code>：若开启，将给定区块内所有的方块都生成并置入对象文件</li> <li><code>byBlockID</code>：若开启，将给定区域内所有指定 ID 的方块都生成并置入对象文件</li> <li><code>byBlockIDData</code>：若开启，将给定区域内所有带指定数据及 ID 的方块都生成并置入对象文件</li> <li><code>byTexture</code>：若开启，将给定区域内所有指定纹理的方块都生成并置入对象文件</li> <li><code>shader</code>：指定导出时使用的着色器。默认使用 <code>stdtexture</code>。目前仅支持基于资源包的着色器。</li></ul> <p><code>/dynmapexp</code> 的子命令如下：</p> <ul><li><code>/dynmapexp set</code>：设置（上述的）导出属性。额外参数都可通过这条命令多次输入指定（如 <code>/dynmapexp set x0 0 y0 0 z0 100</code>）</li> <li><code>/dynmapexp radius</code>：只能由游戏内玩家使用。允许导出以玩家当前（XZ 轴）位置及整个 Y 轴为中心，一定半径范围的世界。</li> <li><code>/dynmapexp info</code>：浏览当前导出设置的属性。</li> <li><code>/dynmapexp pos0</code>：只能由游戏内玩家使用。将导出的 x0、y0、z0 位置及世界设置在玩家当前位置。</li> <li><code>/dynmapexp pos1</code>：只能由游戏内玩家使用。将导出的 x1、y1、z1 位置及世界设置在玩家当前位置。</li> <li><code>/dynmapexp reset</code>：将当前导出设置重置为默认状态。</li> <li><code>/dynmapexp export</code>：开始导出，在服务器 <code>export</code> 文件夹（默认位于 <code>dynmap</code> 下，可通过 <code>configuration.txt</code> 下的 <code>exportpath</code> 参数设置改变）中生成一个 <code>.zip</code> 格式的文件。这个操作是异步的，可能需要几秒到几分钟不等的时间完成，取决于你选择导出的区域大小。</li> <li><code>/dynmapexp purge</code>：删除导出目录中前一次的内容。</li></ul> <p>完成后，你可以在 <code>.zip</code> 压缩包里找到这些内容：</p> <ul><li>一个 minecraft.obj 文件，包含导出的模型（可能会非常大）</li> <li>一个 .mtl 文件，包含材料库（对应 Minecraft 的纹理），用于为 minecraft.obj 中的模型着色</li> <li>一个文件夹，包含材料库使用的贴图文件。</li></ul> <p>若要使用文件，只需解压文件并在渲染软件中载入 <code>minecraft.obj</code> 文件即可。</p> ',18)),a(d),a(t)])}const b=n(l,[["render",p]]);export{_ as __pageData,b as default};
